"""Phase 3.5 real-browser fixtures plus all preserved Phase 3 coverage."""
import argparse,json,unittest
from pathlib import Path
from test_cinematic_world_integration import CinematicWorldIntegration
from test_continuity import RecordedResult
class RefinementIntegration(CinematicWorldIntegration):
    def test_animation_is_physically_sourced_and_pause_reduced_motion_are_static(self):
        p=self.page();self.operations(p);s=self.snap(p);p.evaluate('__icarusSoak.phase3("render")');self.assertEqual(p.locator('#campeople .cam-person').first.get_attribute('data-motion-active'),'false');self.assertEqual(s,self.snap(p));p.emulate_media(reduced_motion='reduce');self.assertEqual(p.locator('#campeople .cam-person .rig-art').first.evaluate('(e)=>getComputedStyle(e).animationName'),'none')
    def test_refined_camera_desktop_and_tablet_screenshots_do_not_mutate_world(self):
        p=self.page();self.advance(p,120);self.operations(p);s=self.snap(p)
        for size,label in [({'width':1440,'height':900},'desktop'),({'width':1280,'height':800},'tablet')]:
            p.set_viewport_size(size);p.locator('#camera-scene').screenshot(path='/workspace/work/phase35_reports/35a_'+label+'.png');self.assertEqual(self.snap(p),s)
    def test_single_writer_tabs_and_immediate_crash_reopen_preserve_voyage(self):
        p=self.page();self.advance(p,120);self.assertTrue(p.evaluate('__icarusSoak.save()'));s=self.snap(p);q=p.context.new_page();q.goto(self.url);q.wait_for_function('!!window.__icarusSoak');self.assertFalse(q.evaluate('ICARUSDurable.canWrite()'));self.assertFalse(q.evaluate('__icarusSoak.save()'));self.advance(q,120);self.assertEqual(self.snap(q),s);p.close();q.reload();q.wait_for_function('!!window.__icarusSoak');self.assertTrue(q.evaluate('ICARUSDurable.canWrite()'));self.assertEqual(self.snap(q),s);self.advance(q,1);self.assertEqual(self.snap(q)['tick'],121)
    def streamed(self,p):
        p.locator('#icarus-menu button[data-page="settings"]').click();
        if not p.locator('#savemanager').evaluate('(e)=>e.open'):p.locator('#savemanager > summary').click()
        p.evaluate('window.showSaveFilePicker=undefined');self.assertTrue(p.evaluate('__icarusSoak.save()'))
        with p.expect_download() as d:p.locator('#export-stream').click()
        p.wait_for_function('!ICARUSBackupUI.busy()');return Path(d.value.path()).read_bytes()
    def test_streamed_long_history_uses_cursor_and_roundtrips_without_truncation(self):
        p=self.page();self.advance(p,240);p.evaluate("async()=>{await ICARUSDurable.importHistory(Array.from({length:4096},(_,i)=>({id:'EXPLICIT-LONG-HISTORY-'+i,kind:'test-fixture',minute:480,episode:1,people:[],data:{fixture:true}})));await ICARUSDurable.flush();const get=IDBObjectStore.prototype.getAll;IDBObjectStore.prototype.getAll=function(...args){if(this.name==='history')throw Error('Unbounded history read in streaming path');return get.apply(this,args);};}");s=self.snap(p);data=self.streamed(p);lines=[json.loads(x) for x in data.splitlines()];self.assertEqual(lines[-1]['records'],sum(len(x['records']) for x in lines if x.get('type')=='history'));self.assertGreaterEqual(lines[-1]['records'],4096);p.on('dialog',lambda d:d.accept());p.locator('#backupfile').set_input_files({'name':'actual-export.ndjson','mimeType':'application/x-ndjson','buffer':data});p.wait_for_function('document.querySelector("#backup-progress").textContent.includes("committed")');self.assertEqual(self.snap(p),s);p.reload();self.assertEqual(self.snap(p),s);self.assertGreaterEqual(p.evaluate('ICARUSDurable.history().then(x=>x.length)'),4096)
    def test_corrupted_or_interrupted_stream_never_replaces_current_world(self):
        p=self.page();self.advance(p,120);data=self.streamed(p);s=self.snap(p);p.on('dialog',lambda d:d.accept());lines=data.splitlines()
        tampered=p.evaluate("text=>{const rows=text.trim().split('\\n').map(JSON.parse);const chunk=rows.find(x=>x.type==='history');chunk.records[0].kind='tampered';return rows.map(JSON.stringify).join('\\n')+'\\n';}",data.decode()).encode()
        for corrupt in [b'\n'.join(lines[:-1])+b'\n',data.replace(b'"chain":"',b'"chain":"CORRUPT',1),tampered]:
            p.evaluate('document.querySelector("#backup-progress").textContent="Starting corrupt fixture"')
            p.locator('#backupfile').set_input_files({'name':'broken.ndjson','mimeType':'application/x-ndjson','buffer':corrupt});p.wait_for_function('!ICARUSBackupUI.busy()&&document.querySelector("#backup-progress").textContent.includes("Import stopped")');self.assertEqual(self.snap(p),s)
        p.reload();self.assertEqual(self.snap(p),s)
    def test_cancel_and_atomic_import_abort_keep_original_committed_revision(self):
        p=self.page();self.advance(p,120);data=self.streamed(p);s=self.snap(p);p.on('dialog',lambda d:d.accept());p.evaluate('window.__icarusAbortNextImport=true');p.locator('#backupfile').set_input_files({'name':'abort.ndjson','mimeType':'application/x-ndjson','buffer':data});p.wait_for_function('!ICARUSBackupUI.busy()&&document.querySelector("#backup-progress").textContent.includes("Import stopped")');self.assertEqual(self.snap(p),s);p.reload();self.assertEqual(self.snap(p),s)
    def test_cancel_after_staged_chunk_keeps_original_world_and_sources(self):
        p=self.page();self.advance(p,120);data=self.streamed(p);s=self.snap(p);result=p.evaluate("""async text=>{const c=new AbortController();let applied=false;try{await ICARUSBackupTransfer.importFile(new File([text],'cancel.ndjson'),{signal:c.signal,validate:p=>!!p.state,confirm:()=>true,apply:()=>applied=true,progress:msg=>{if(msg.includes('staged'))c.abort();}});return {failed:false,applied};}catch(e){return {failed:e.message.includes('Cancelled'),applied};}}""",data.decode());self.assertEqual(result,{'failed':True,'applied':False});self.assertEqual(self.snap(p),s);p.reload();self.assertEqual(self.snap(p),s)
    def test_writable_file_stream_sink_uses_real_browser_filesystem_api(self):
        p=self.page();self.advance(p,120);p.locator('#icarus-menu button[data-page="settings"]').click();p.locator('#savemanager > summary').click();p.evaluate("window.showSaveFilePicker=async()=>{const dir=await navigator.storage.getDirectory();return dir.getFileHandle('explicit-export-fixture.ndjson',{create:true});}");p.locator('#export-stream').click();p.wait_for_function('document.querySelector("#backup-progress").textContent.includes("Complete streamed")');text=p.evaluate("navigator.storage.getDirectory().then(d=>d.getFileHandle('explicit-export-fixture.ndjson')).then(h=>h.getFile()).then(f=>f.text())");self.assertEqual(json.loads(text.splitlines()[-1])['type'],'end')
    def test_indexeddb_lease_fallback_protects_insecure_lan_contexts(self):
        c=self.browser.new_context();self.contexts.append(c);c.add_init_script(self.codec+";Object.defineProperty(navigator,'locks',{value:undefined});window.__icarusSeed=10101;");p=c.new_page();p.goto(self.url);p.wait_for_function('!!window.__icarusSoak');self.assertTrue(p.evaluate('ICARUSDurable.canWrite()'));self.assertTrue(p.evaluate('__icarusSoak.save()'));q=c.new_page();q.goto(self.url);q.wait_for_function('!!window.__icarusSoak');self.assertFalse(q.evaluate('ICARUSDurable.canWrite()'));self.assertFalse(q.evaluate('__icarusSoak.save()'))
    def test_storage_fencing_rejects_stale_writer_and_recovers_committed_world(self):
        p=self.page();self.advance(p,120);self.assertTrue(p.evaluate('__icarusSoak.save()'));s=self.snap(p);self.advance(p,60);p.evaluate("async()=>{const d=await new Promise(ok=>{const r=indexedDB.open(ICARUSEdition.database,1);r.onsuccess=()=>ok(r.result);});await new Promise(ok=>{const t=d.transaction('meta','readwrite');t.objectStore('meta').put({key:'writer',owner:'EXPLICIT-CONFLICT-FIXTURE',token:999,expires:Date.now()+15000});t.oncomplete=ok;});d.close();}");self.assertFalse(p.evaluate('__icarusSoak.save()'));self.assertFalse(p.evaluate('ICARUSDurable.canWrite()'));p.reload();self.assertEqual(self.snap(p),s)
if __name__=='__main__':
    ap=argparse.ArgumentParser();ap.add_argument('--report',default='refinement.json');args=ap.parse_args();r=unittest.TextTestRunner(verbosity=2,resultclass=RecordedResult).run(unittest.defaultTestLoader.loadTestsFromTestCase(RefinementIntegration));Path(args.report).write_text(json.dumps({'passed':r.wasSuccessful(),'tests_run':r.testsRun,'passed_cases':r.successes,'failures':[{'test':str(t),'detail':d} for t,d in r.failures],'errors':[{'test':str(t),'detail':d} for t,d in r.errors]},indent=2));raise SystemExit(not r.wasSuccessful())
